ctlAPB:
        DEC     cursorCol               ; C0 $08 APB - cursor back
        JSR     $EC16
        JMP     parseNextByte

ctlAPF:
        INC     cursorCol               ; C0 $09 APF - cursor forward
        JSR     $EC16
        JMP     parseNextByte

ctlAPD:
        TST     $04AF                   ; C0 $0A APD - cursor down
        BPL     $DA5D
        JMP     parseNextByte
        JSR     $EE3A
        TST     $04A3
        BPL     $DA73
        LDAA    cursorRow
        CMPA    scrollBottom
        BNE     $DA73
        JSR     $EA44
        JMP     parseNextByte
        INC     cursorRow
        JSR     $EC16
        JSR     $E9A5
        JMP     parseNextByte

ctlAPU:
        TST     $04AF                   ; C0 $0B APU - cursor up
        BPL     $DA87
        JMP     parseNextByte
        JSR     $EE3A
        TST     $04A3
        BPL     $DA9D
        LDAA    cursorRow
        CMPA    scrollTop
        BNE     $DA9D
        JSR     $EB28
        JMP     parseNextByte
        DEC     cursorRow
        JSR     $EC16
        JSR     $E9A5
        JMP     parseNextByte

ctlCS:
        TST     $04AF                   ; C0 $0C CS - clear screen
        BPL     $DAB1
        JMP     parseNextByte
        LDAA    #$FF
        STAA    scrollTop
        STAA    scrollBottom
        STAA    $04A3
