        LDAA    $1B25
        STAA    $1B23
        CLR     $0495
        CLR     $1B24
        CLR     $1B25
        JMP     ctlAPH

ctlAPR:
        CLR     cursorCol               ; C0 $0D APR - cursor to start of line
        JSR     $EC16
        JSR     $E9A5
        JMP     parseNextByte

ctlSO:
        TST     $04AF                   ; C0 $0E SO - shift out to G1
        BPL     $DAF0
        JMP     parseNextByte
        LDAA    #$01
        STAA    $049D
        STAA    $04A2
        JMP     parseNextByte

ctlSI:
        TST     $04AF                   ; C0 $0F SI - shift in to G0
        BPL     $DB03
        JMP     parseNextByte
        LDAA    #$00
        STAA    $049D
        STAA    $04A2
        JMP     parseNextByte

ctlCON:
        TST     $04AF                   ; C0 $11 CON - cursor on
        BPL     $DB16
        JMP     parseNextByte
        LDAA    #$FF
        STAA    $1B20
        LDX     rowChar
        LDAB    cursorCol
        ABX
